# Let me check which distance is duplicated
def verify_golomb_detailed(ruler):
    distances = {}
    for i in range(len(ruler)):
        for j in range(i+1, len(ruler)):
            d = ruler[j] - ruler[i]
            if d in distances:
                print(f"Duplicate distance {d}: ({ruler[distances[d][0]]},{ruler[distances[d][1]]}) and ({ruler[i]},{ruler[j]})")
                return False
            distances[d] = (i, j)
    return True

verify_golomb_detailed([0, 1, 3, 7, 12, 20, 22, 25, 41, 45, 66])

# Try another known 11-mark Golomb ruler
# The optimal one has length 72
rulers_to_try = [
    [0, 1, 3, 7, 12, 20, 22, 25, 41, 45, 66],
    [0, 2, 7, 13, 21, 22, 32, 35, 40, 51, 72],  # another candidate
    [0, 1, 3, 7, 12, 20, 30, 44, 65, 80, 96],
]

for r in rulers_to_try:
    valid = verify_golomb_detailed(r)
    print(f"{r}: valid={valid}")
